    async def read_file(
        self,
        trunk_id: str,
        context_key: str,
        resource_path: str,
        *,
        ref: str,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> typing.AsyncIterator[bytes]:
        """
        Parameters
        ----------
        trunk_id : str

        context_key : str

        resource_path : str

        ref : str
            Immutable revision ID from inspect; resolve moving channels before reading.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration. You can pass in configuration such as `chunk_size`, and more to customize the request and response.

        Returns
        -------
        typing.AsyncIterator[bytes]
            Digest-verified bytes, bounded to 1,000,000 bytes.

        Examples
        --------
        import asyncio

        from agenttrunk import AsyncAgentTrunk

        client = AsyncAgentTrunk(
            access_token="YOUR_ACCESS_TOKEN",
        )


        async def main() -> None:
            await client.contexts.read_file(
                trunk_id="trunkId",
                context_key="contextKey",
                resource_path="resourcePath",
                ref="ref",
            )


        asyncio.run(main())
        """
        async with self._raw_client.read_file(
            trunk_id, context_key, resource_path, ref=ref, request_options=request_options
        ) as r:
            async for _chunk in r.data:
                yield _chunk
